<script setup lang="ts">
useSeoPage('Reset password', 'Request a secure password reset link for your 247URL account.', '/forgot-password')
const email=ref(''); const loading=ref(false); const complete=ref(false); const error=ref(''); const {request}=useApi()
async function submit(){loading.value=true;error.value='';try{await request('auth/forgot-password',{method:'POST',body:{email:email.value}});complete.value=true}catch(e:any){error.value=e?.data?.message||'Unable to request a reset link.'}finally{loading.value=false}}
</script>
<template><AuthShell title="Reset your password" description="Enter your email and we’ll send reset instructions if the account exists."><div v-if="complete" class="rounded-lg border border-success-border bg-success-bg p-5"><p class="font-medium text-success">Check your inbox</p><p class="mt-2 text-sm text-text-secondary">If an account exists for that address, a reset link has been sent.</p><NuxtLink to="/login" class="btn-secondary mt-5">Back to sign in</NuxtLink></div><form v-else class="grid gap-5" @submit.prevent="submit"><div><label class="label" for="email">Email address</label><input id="email" v-model="email" class="input" type="email" autocomplete="email" required></div><p v-if="error" class="field-error" role="alert">{{ error }}</p><button class="btn-primary w-full" :disabled="loading">{{ loading?'Sending…':'Send reset link' }}</button></form></AuthShell></template>
